define({"topics":[{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_56.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e202491","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_53.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e202595","topics":[]},{"title":"Removing the ISC top fan assembly","shortdesc":"<p class=\"shortdesc\">Remove the Integrated System Cabinet (ISC) top fan assembly.<\/p>","href":"t_ReplacingTheISCTopFan.html","attributes":{"data-id":"id_2007001"},"menu":{"hasChildren":false},"tocID":"id_2007001-d46e202699","topics":[]},{"title":"Installing the ISC top fan assembly","shortdesc":"<p class=\"shortdesc\">Install the Integrated System Cabinet (ISC) top fan assembly.<\/p>","href":"t_InstallingTheISCTopFanAssembly.html","attributes":{"data-id":"id_2015319"},"menu":{"hasChildren":false},"tocID":"id_2015319-d46e202803","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_55.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e202907","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_55.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e203011","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_82.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e203115","topics":[]}]});